$_LANG['closewindow'] = "Zamknij okno";
$_LANG['cloudSlider']['feature01Description'] = "Dostępność serwerów jest kluczowa dla każdej firmy - to bicie serca hostingu biznesu. Serwery plików i baz danych, poczty i stron WWW są niezbędną częścią większości procesów biznesowych, a przestoje bezpośrednio obniżają produktywność, sprzedaż oraz zadowolenie pracowników i klientów. Dlatego zapewnienie maksymalnej dostępności serwerów jest dla nas tak ważne - chcemy, aby procesy w firmie działały sprawnie, a klienci byli zadowoleni.";
$_LANG['cloudSlider']['feature01DescriptionTwo'] = "Powierzając nam potrzeby swojej firmy, otrzymujesz gwarancję 99,9% dostępności wszystkich świadczonych przez nas usług, z wyłączeniem standardowych prac konserwacyjnych.";
$_LANG['cloudSlider']['feature01Title'] = "Maksymalna dostępność serwerów";
$_LANG['cloudSlider']['feature02Description'] = "Nasze usługi działają w oparciu o setki serwerów i centrów danych na całym świecie, więc masz pewność, że klienci uzyskają dostęp do strony z dowolnego miejsca. Dodatkowo udostępniamy narzędzia monitorujące i profesjonalną analitykę - ruch na stronie to ważny element poprawy jej wydajności i popularności, a także śledzenia, skąd pochodzą odwiedzający, o jakiej porze dnia odwiedzają stronę i jak długo na niej pozostają. Nasze zaangażowanie w rynek globalny obejmuje także rejestrację domen - oferujemy najpopularniejsze domeny TLD.";
$_LANG['cloudSlider']['feature02DescriptionTwo'] = "Nasze zaangażowanie w obsługę klienta również sięga całego świata. Chętnie pomożemy w sprawach związanych z hostingiem na każdy możliwy sposób - można się z nami skontaktować telefonicznie, e-mailem lub przez czat na żywo.";
$_LANG['cloudSlider']['feature02Title'] = "Dostarczanie danych na całym świecie";
$_LANG['cloudSlider']['feature03Description'] = "Zapewniamy całodobowy monitoring bezpieczeństwa i ochronę przed atakami DDoS. Ochronę danych klientów traktujesz poważnie, tak jak my. Nasz zespół ds. bezpieczeństwa i zabezpieczenia działają codziennie, aby zapewnić poziom ochrony wymagany w dzisiejszej erze cyfrowej.";
$_LANG['cloudSlider']['feature03DescriptionTwo'] = "Do dyspozycji jest szeroka gama narzędzi bezpieczeństwa, w tym certyfikaty SSL, konfiguracja zapory, usługi monitorowania bezpieczeństwa, dostęp VPN i wiele więcej.";
$_LANG['cloudSlider']['feature03Title'] = "Najwyższy poziom bezpieczeństwa";
