$_LANG['ssl']['approverEmailProcess'] = "<h4>Informacje o procesie e-maila zatwierdzającego</h4><p>Aby wydać certyfikat SSL, urząd certyfikacji musi zweryfikować autentyczność zamówienia certyfikatu, aby upewnić się, że żądanie jest prawidłowe i pochodzi od uprawnionego właściciela domeny.</p><p>Weryfikacja domeny za pomocą e-maila jest najpopularniejszym mechanizmem weryfikacji zamówień certyfikatów. Urząd certyfikacji tworzy listę zatwierdzonych adresów e-mail na podstawie popularnych adresów administracyjnych (na przykład admin lub webmaster) w połączeniu z publicznymi danymi WHOIS domeny. Do potwierdzenia własności można użyć tylko jednego z tych adresów e-mail.</p>";
$_LANG['ssl']['approverEmailUpdateInfo'] = "<p>Wkrótce na adres <em>:newApproverEmail</em> zostanie wysłany e-mail z prośbą o zatwierdzenie certyfikatu.</p><p>Jeśli e-mail nie dotrze, sprawdź filtry spamu i foldery ochrony antywirusowej – wiadomość mogła zostać poddana kwarantannie. Jeśli nadal nie możesz jej znaleźć, <a href=\"submitticket.php\">skontaktuj się z pomocą techniczną</a>.</p>";
