$_LANG['store']['addon']['wptk']['faqQ7'] = "Jak uzyskać dostęp do WP Toolkit?";
$_LANG['store']['addon']['wptk']['featureBody1'] = "Instalacja i konfiguracja wtyczek oraz motywów pozwala dostosować wygląd dowolnej (lub wszystkich) witryn WordPress jednocześnie, kilkoma kliknięciami.";
$_LANG['store']['addon']['wptk']['featureBody2'] = "Można sklonować dowolną istniejącą witrynę WordPress, aby testować projekty, wtyczki lub dowolny aspekt witryny, a następnie w dowolnym momencie zsynchronizować zmiany z działającą witryną.";
$_LANG['store']['addon']['wptk']['featureBody3'] = "Jedno kliknięcie przycisku przeskanuje i zabezpieczy witryny WordPress przed wybranymi zagrożeniami. Można też chronić hasłem wybrane witryny lub strony.";
$_LANG['store']['addon']['wptk']['featureBody4'] = "Smart Updates automatycznie wykrywa i analizuje aktualizacje pod kątem zgodności i bezpieczeństwa, a następnie je instaluje lub powiadamia o problemach, zapewniając bezpieczeństwo witryny.";
$_LANG['store']['addon']['wptk']['featureBody5'] = "Utworzenie kopii działającej witryny do eksperymentów przy jednoczesnej ochronie wszystkich witryn WordPress jednym kliknięciem.";
$_LANG['store']['addon']['wptk']['featureBody6'] = "Wyłącz witrynę, wyświetlając niestandardowy komunikat.";
