$_LANG['store']['addon']['wptk']['for'] = "dla";
$_LANG['store']['addon']['wptk']['getItNow'] = "Zamów teraz";
$_LANG['store']['addon']['wptk']['getStartedToday'] = "Zacznij korzystać z WP Toolkit Deluxe już dziś!";
$_LANG['store']['addon']['wptk']['introBody'] = "Pozbądź się domysłów i żmudnej pracy przy zarządzaniu WordPressem. Poza wszystkim, czego można oczekiwać — od łatwych kopii zapasowych i przywracania, przez zarządzanie indeksowaniem w wyszukiwarkach, po logowanie do WordPressa jednym kliknięciem — dostajesz też automatyczne Smart Updates, środowisko testowe i klonowanie do łatwego duplikowania lub testowania istniejących witryn, zabezpieczanie jednym kliknięciem i wiele więcej!";
$_LANG['store']['addon']['wptk']['introTitle'] = "WP Toolkit Deluxe zapewnia zaawansowane zarządzanie wtyczkami i motywami WordPress, zabezpieczanie, automatyzację, klonowanie oraz kopie zapasowe i przywracanie — wszystko w jednym przyjaznym panelu.";
