$_LANG['store']['addon']['wptk']['plesk']['featureBody1'] = "Instalator jednym kliknięciem do inicjalizacji i konfiguracji WordPressa od początku do końca. Jeden panel do zbiorowego zarządzania wieloma instancjami WordPress.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody2'] = "Testowanie nowych funkcji i pomysłów w środowisku testowym przed wdrożeniem na produkcję – bez wtyczek i bez osobnego serwera.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody3'] = "Domyślnie zabezpiecza witrynę, a skaner bezpieczeństwa WP Toolkit dodatkowo ją wzmacnia. Nie jest potrzebna wiedza z zakresu bezpieczeństwa.";
$_LANG['store']['addon']['wptk']['plesk']['featureBody4'] = "Aktualizacja pojedyncza lub zbiorowa WordPressa, jego motywów i wtyczek. Monitorowanie wszystkich witryn WordPress i zarządzanie nimi z jednego panelu.";
