$_LANG['store']['emailServices']['benefits']['archiving']['6'] = "Dodatkowa ciągłość poczty e-mail, obsługa dziennikowania i łatwe ponowne dostarczanie";
$_LANG['store']['emailServices']['benefits']['archiving']['7'] = "Skompresowane, szyfrowane i bezpieczne archiwum";
$_LANG['store']['emailServices']['benefits']['archiving']['a1'] = "Archiwizacja poczty e-mail zachowuje i chroni wszystkie wiadomości przychodzące i wychodzące na potrzeby późniejszego dostępu. To doskonały sposób na odzyskanie utraconych lub przypadkowo usuniętych wiadomości, przyspieszenie odpowiedzi na audyty, zabezpieczenie wiadomości i załączników stanowiących własność intelektualną, a także na potrzeby „eDiscovery” w przypadku postępowania sądowego.";
$_LANG['store']['emailServices']['benefits']['archiving']['a2a'] = "Rozpaczliwie szukasz ważnej wiadomości z zeszłego roku, ale nie możesz jej znaleźć, a z tego powodu grozi Ci kara lub utrata ważnego kontraktu? Zapobiegnij temu dzięki profesjonalnemu rozwiązaniu do archiwizacji poczty e-mail. Archiwizacja poczty e-mail to kluczowe narzędzie do zachowania bezpiecznej kopii wszystkich wiadomości i zapewnienia zgodności z prawem.";
$_LANG['store']['emailServices']['benefits']['archiving']['a2b'] = "Jednocześnie, ponieważ korespondencja e-mail ma moc dowodową i jest prawnie wiążąca, zgodność poczty e-mail z przepisami stała się niezwykle ważną kwestią dla organizacji. Dlatego w niektórych branżach obowiązkowe jest przechowywanie bezpiecznej kopii wszystkich wiadomości e-mail i zachowanie zgodności z prawem.";
$_LANG['store']['emailServices']['benefits']['archiving']['q1'] = "Archiwizacja poczty e-mail";
