$_LANG['store']['emailServices']['benefits']['archiving']['title'] = "Archiwizacja poczty e-mail zapewnia wszystkie te korzyści...";
$_LANG['store']['emailServices']['benefits']['incoming']['1'] = "Pełna ochrona skrzynki odbiorczej w konkurencyjnych cenach";
$_LANG['store']['emailServices']['benefits']['incoming']['2'] = "Niezwykle dokładne filtrowanie";
$_LANG['store']['emailServices']['benefits']['incoming']['3'] = "Łatwa konfiguracja";
$_LANG['store']['emailServices']['benefits']['incoming']['4'] = "Zwiększona ciągłość i redundancja poczty przychodzącej";
$_LANG['store']['emailServices']['benefits']['incoming']['5'] = "Różne opcje raportowania";
$_LANG['store']['emailServices']['benefits']['incoming']['6'] = "Przyjazny interfejs zapewniający pełną kontrolę nad pocztą e-mail";
$_LANG['store']['emailServices']['benefits']['incoming']['7'] = "Wzrost produktywności pracowników";
$_LANG['store']['emailServices']['benefits']['incoming']['8'] = "Zgodność z dowolnym serwerem poczty";
$_LANG['store']['emailServices']['benefits']['incoming']['a1'] = "Filtrowanie poczty przychodzącej filtruje wszystkie wiadomości przychodzące i eliminuje spam oraz wirusy, zanim zagrożenia te dotrą do sieci, ze skutecznością bliską 100%. Rozbudowany panel sterowania zapewnia pełną kontrolę. Ponadto w przypadku awarii serwera poczty wiadomości są kolejkowane. Wiadomości z kolejki można przeglądać, czytać i odpowiadać na nie przez interfejs internetowy, co zwiększa ciągłość poczty przychodzącej!";
$_LANG['store']['emailServices']['benefits']['incoming']['a2'] = "Nie ryzykuj zagrożeń dla sieci IT. Jeśli skrzynka odbiorcza jest codziennie zapełniona niechcianą masową pocztą, to znak, że potrzebne jest profesjonalne rozwiązanie do filtrowania poczty przychodzącej. Zapewnij skrzynce pełną ochronę i pożegnaj się ze spamem, wirusami i złośliwym oprogramowaniem!";
$_LANG['store']['emailServices']['benefits']['incoming']['a3'] = "Gdy domena zostanie (automatycznie) przypisana do filtra poczty przychodzącej, a filtrowanie zostanie aktywowane, poczta będzie przechodzić przez chmurę filtrującą SpamExperts. Wiadomości przychodzące są bezpiecznie analizowane i skanowane w czasie rzeczywistym. Nie jest wymagane żadne szkolenie ani konfiguracja – wszystko działa od razu. Każda wiadomość wykryta jako spam trafia do kwarantanny, a pozostałe są wysyłane na serwer poczty. Kwarantannę można monitorować w przyjaznym panelu SpamPanel, za pomocą raportów e-mail, a nawet bezpośrednio w kliencie poczty! Koniec ze stratą czasu na spam – skup się na zadaniach biznesowych, zachowując pełną kontrolę.";
$_LANG['store']['emailServices']['benefits']['incoming']['q1'] = "Dlaczego warto wybrać filtr poczty przychodzącej SpamExperts?";
$_LANG['store']['emailServices']['benefits']['incoming']['q2'] = "Dlaczego potrzebny jest profesjonalny filtr poczty przychodzącej?";
$_LANG['store']['emailServices']['benefits']['incoming']['q3'] = "Jak to działa";
$_LANG['store']['emailServices']['benefits']['incoming']['title'] = "Filtrowanie poczty przychodzącej zapewnia wszystkie te korzyści...";
$_LANG['store']['emailServices']['benefits']['outgoing']['1'] = "Koniec z czarnymi listami";
$_LANG['store']['emailServices']['benefits']['outgoing']['2'] = "Ochrona reputacji marki i systemów IT";
$_LANG['store']['emailServices']['benefits']['outgoing']['3'] = "Brak kosztów związanych z usuwaniem z czarnych list";
$_LANG['store']['emailServices']['benefits']['outgoing']['4'] = "Zwiększona ciągłość i skuteczność dostarczania poczty wychodzącej";
$_LANG['store']['emailServices']['benefits']['outgoing']['5'] = "Wyższa produktywność pracowników";
$_LANG['store']['emailServices']['benefits']['outgoing']['6'] = "Lepsze zarządzanie nadużyciami";
$_LANG['store']['emailServices']['benefits']['outgoing']['a1'] = "Filtrowanie poczty wychodzącej jest kluczowe dla ochrony reputacji infrastruktury IT i zapewnienia, że cała poczta wychodząca bezpiecznie dociera do adresatów. To profesjonalne rozwiązanie blokuje wysyłanie spamu i wirusów z sieci i zapobiega umieszczeniu adresów IP na czarnych listach. Ponadto filtr poczty wychodzącej SpamExperts udostępnia raporty i narzędzia do wykrywania przejętych kont oraz blokowania użytkowników wysyłających spam.";
$_LANG['store']['emailServices']['benefits']['outgoing']['a2'] = "Czy Twoja sieć kiedykolwiek wysłała spam bez Twojej wiedzy? Z powodu słabości sieci niemal każde urządzenie może zostać przejęte i wykorzystane do wysyłania wychodzących wiadomości SMTP, co pozwala rozsyłać spam lub złośliwe oprogramowanie z Twojej sieci bez Twojej wiedzy! Dlatego warto zainwestować w profesjonalne rozwiązanie do filtrowania poczty wychodzącej. Dbaj o dobrą reputację firmy, nie dopuszczaj do wysyłania spamu z sieci i unikaj czarnych list, aby poczta zawsze docierała tam, gdzie powinna.";
$_LANG['store']['emailServices']['benefits']['outgoing']['q1'] = "Czym jest filtrowanie poczty wychodzącej?";
