$_LANG['store']['ox']['cartShortDescription'] = "Profesjonalna poczta e-mail klasy biznesowej z w pełni funkcjonalnymi narzędziami do komunikacji i współpracy, zapewniająca bezpieczną i niezawodną pracę.";
$_LANG['store']['ox']['cartTitle'] = "Profesjonalna poczta e-mail";
$_LANG['store']['ox']['faq1']['answer'] = "Wszystkie plany OX App Suite zawierają dostęp do poczty Webmail, Kalendarza, Zadań i Książki adresowej. Pakiet Productivity dodaje OX Drive oraz OX Documents (Tekst, Arkusze kalkulacyjne i Prezentacje).";
$_LANG['store']['ox']['faq1']['question'] = "Jakie aplikacje są zawarte w OX App Suite?";
$_LANG['store']['ox']['faq2']['answer'] = "Tak, OX App Suite obsługuje połączenie wszystkich zewnętrznych kont e-mail IMAP, w tym popularnych dostawców, takich jak Gmail, Yahoo i Outlook.com. Wystarczy dodać adres e-mail i hasło w App Suite, a każda wiadomość wysłana na te konta pojawi się w interfejsie App Suite.";
$_LANG['store']['ox']['faq2']['question'] = "Czy mogę dodać zewnętrzne konta e-mail do OX App Suite?";
$_LANG['store']['ox']['faq3']['answer'] = "Tak, OX App Suite w pełni obsługuje CalDAV i CardDAV. Dla użytkowników Androida synchronizacja jest prosta dzięki dedykowanej aplikacji Android Sync.";
$_LANG['store']['ox']['faq3']['question'] = "Czy mogę synchronizować kalendarz i kontakty między OX App Suite a urządzeniem mobilnym?";
$_LANG['store']['ox']['faq4']['answer'] = "App Suite działa bezproblemowo z większością natywnych klientów poczty na komputery i urządzenia mobilne.";
$_LANG['store']['ox']['faq4']['devices'] = "Urządzenia mobilne: iPhone z systemem iOS 11/iOS 12, smartfon z systemem Android 4.1 lub nowszym<br>Obsługiwane przeglądarki: Safari, Chrome (najnowsza i poprzednia wersja), Mozilla Firefox (najnowsza i poprzednia wersja), Microsoft Internet Explorer 11/Edge";
$_LANG['store']['ox']['faq4']['question'] = "Czy OX App Suite będzie działać na moim urządzeniu?";
$_LANG['store']['ox']['faq5']['answer'] = "Tak! OX App Suite wykorzystuje własną technologię oraz współpracę z renomowanymi dostawcami z branży ochrony antyspamowej, aby skrzynka odbiorcza pozostawała jak najczystsza i najbezpieczniejsza.";
$_LANG['store']['ox']['faq5']['question'] = "Czy OX App Suite chroni przed spamem i wirusami?";
$_LANG['store']['ox']['faq6']['answer'] = "OX Drive to internetowe rozwiązanie do przechowywania dokumentów, zdjęć i multimediów w chmurze. Oznacza to, że wystarczy dostęp do OX App Suite i OX Drive, aby mieć dostęp także do wszystkich plików. OX Drive umożliwia synchronizację plików ze wszystkimi urządzeniami za pomocą przeglądarki lub aplikacji natywnych.";
$_LANG['store']['ox']['faq6']['question'] = "Czym jest OX Drive (Productivity)?";
$_LANG['store']['ox']['faq7']['answer'] = "OX Text, OX Spreadsheet i OX Presentation to 3 aplikacje wchodzące w skład szerszego pojęcia OX Documents. Aplikacje te umożliwiają tworzenie i edycję dokumentów tekstowych, arkuszy kalkulacyjnych i prezentacji online. Dokumenty można tworzyć i edytować z dowolnego miejsca, korzystając ze znanych funkcji pakietu biurowego, na wszystkich urządzeniach.";
$_LANG['store']['ox']['faq7']['question'] = "Czym jest OX Documents (Productivity)?";
$_LANG['store']['ox']['faq8']['answer'] = "OX App Suite obsługuje następujące języki: angielski, niemiecki, hiszpański, francuski, włoski, holenderski, polski, 中文 简体, 中文 繁體, 日本語";
$_LANG['store']['ox']['faq8']['question'] = "Jakie języki obsługuje OX App Suite?";
$_LANG['store']['ox']['faq9']['answer'] = "Tak, oferujemy samoobsługowe narzędzie do migracji, które jest intuicyjne i łatwe w użyciu. Można migrować ze wszystkich popularnych usług pocztowych, w tym Apple iCloud, Gmail, Outlook.com/Windows Live/Hotmail, Yahoo Mail, GMX lub T-Online, albo ręcznie wprowadzić dane dostawcy przy użyciu IMAP/POP3 lub innych dostępnych protokołów.";
$_LANG['store']['ox']['faq9']['question'] = "Czy mogę przenieść istniejące konto e-mail od innego dostawcy?";
$_LANG['store']['ox']['feature1']['detail'] = "Przechowuj i udostępniaj ważne dokumenty bezpiecznie w chmurze. Dzięki miejscu do 50 GB masz zapas na długie lata.";
$_LANG['store']['ox']['feature1']['title'] = "Przechowywanie plików w chmurze";
$_LANG['store']['ox']['feature2']['detail'] = "Komunikuj się jak duża firma dzięki wspólnym kalendarzom, kreatorowi planowania spotkań, obsłudze iCal i Globalnej Książce Adresowej!";
$_LANG['store']['ox']['feature2']['title'] = "Kalendarz i kontakty";
$_LANG['store']['ox']['feature3']['detail'] = "Wszystkie ulubione funkcje poczty są tutaj, w tym przekierowania, aliasy, autoresponder, filtry, podpisy, powiadomienia i wiele więcej!";
$_LANG['store']['ox']['feature3']['title'] = "Mnóstwo funkcji poczty e-mail";
$_LANG['store']['ox']['feature4']['detail'] = "Twórz, edytuj i udostępniaj dokumenty Microsoft Office, takie jak Word, Excel i PowerPoint, za pomocą wydajnych aplikacji online App Suite.";
$_LANG['store']['ox']['feature4']['title'] = "Dodaj aplikacje zwiększające produktywność!";
$_LANG['store']['ox']['feature5']['detail'] = "Z łatwością dodaj ulubione usługi poczty i/lub aplikacje do App Suite, takie jak Gmail, Dropbox, Zoom (wkrótce) i inne!";
