$_LANG['store']['siteBuilder']['featuresStore'] = "Sklep internetowy";
$_LANG['store']['siteBuilder']['featuresTitle'] = "Funkcje kreatora stron";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['1'] = "Podziel się swoją historią i nawiąż kontakt z odwiedzającymi, dodając do strony konfigurowalny blog. Skonfiguruj wygląd wpisów na opublikowanej stronie.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['2'] = "Utwórz wpis na blogu teraz, aby zapisać go i opublikować później, np. z okazji konkretnej wiadomości lub specjalnej promocji.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['3'] = "Wprowadzaj zmiany we wpisie po jego opublikowaniu za pomocą wbudowanego narzędzia i edytora treści.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['4'] = "Zachęć odwiedzających do polubienia i udostępniania treści, dodając do strony ikony platform społecznościowych, takich jak Facebook, Twitter, LinkedIn i Pinterest.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['5'] = "Umożliw odwiedzającym komentowanie i polubienie powiązanej strony na Facebooku bez opuszczania witryny.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['6'] = "Automatycznie prezentuj zdjęcia z Instagrama na stronie przy każdej publikacji i informuj odwiedzających, wyświetlając aktualny kanał konta na Twitterze.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['1'] = "Edytor przeciągnij i upuść pozwala klientom dodawać i rozmieszczać elementy strony bezpośrednio na stronie, z predykcyjnym podświetlaniem miejsc do umieszczenia.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['2'] = "Można użyć gotowych elementów układu, takich jak tekst, przyciski, zdjęcia lub ikony, aby zbudować dowolny profesjonalnie wyglądający układ strony.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['3'] = "Nie trzeba tracić czasu na układanie treści. Kolekcja ponad 350 bloków treści pomaga budować profesjonalne strony bez umiejętności technicznych.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['4'] = "Strony będą wyglądać świetnie na każdym urządzeniu. Szablony są w 100% responsywne na wszystkich urządzeniach, w tym smartfonach, tabletach i komputerach.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['5'] = "Wzbogać stronę dzięki wyborowi ponad 200 000 profesjonalnych zdjęć premium w wysokiej rozdzielczości. Nasz kreator stron zawiera także osadzane filmy i optymalizację obrazów.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['6'] = "Dzięki zapisowi w czasie rzeczywistym można mieć pewność, że żadna praca nie zostanie utracona. Edytor automatycznie zapisuje wszystko w trakcie pracy.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['1'] = "Niezależnie od tego, czy to butik, mały sklep czy pełnoprawny sklep internetowy, dostępne są plany na 10, 50 i 500 produktów.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['10'] = "Otrzymuj natychmiast powiadomienia o zamówieniach e-mailem. Zarządzaj wszystkimi zamówieniami i przeglądaj ich zestawienie, wyszukuj je, filtruj według kategorii, aktualizuj zamówienia i dane klientów oraz dodawaj numer śledzenia przesyłki.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['2'] = "Połącz sklep z Paypal, Square, Stripe i ponad 50 zaufanymi dostawcami płatności kartą, aby natychmiast akceptować płatności kartą.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['3'] = "Zapewnij klientom szybsze i łatwiejsze składanie zamówień dzięki opcjonalnej rejestracji podczas finalizacji. Udostępnij bezpieczny jednostronicowy proces zamówienia z możliwością dodania komentarza do zamówienia.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['5'] = "Wybierz spośród wielu układów strony produktu i dostosuj opisy oraz wygląd według uznania. Ułatw klientom znajdowanie produktów, porządkując je w kategorie.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['6'] = "Twórz kupony rabatowe lub kody promocyjne, aby zwiększyć sprzedaż. Zwiększ konwersję, pokazując ceny regularne obok cen po rabacie.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['7'] = "Śledzenie zapasów pomaga ustalić, kiedy należy uzupełnić stan produktu i które warianty produktów cieszą się największą popularnością.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['8'] = "Można oferować klientom stawki przewoźników w czasie rzeczywistym przy zamówieniu, łącząc sklep internetowy z firmą kurierską, taką jak USPS, FedEx, UPS, Australia Post, Canada Post itp.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['9'] = "Stosuj naliczanie podatków dla dowolnego kraju lub zdefiniuj określone strefy. Miej pełną kontrolę nad podatkami: ustaw je według lokalizacji, dodaj podatek dla grupy produktów lub skonfiguruj produkty zwolnione z podatku.";
$_LANG['store']['siteBuilder']['intro1'] = "Stworzenie obecności w sieci wymaga odpowiedniej platformy. Zyskaj widoczność dzięki naszemu kreatorowi stron typu przeciągnij i upuść.";
$_LANG['store']['siteBuilder']['intro2'] = "Niezależnie od tego, czy chcesz promować siebie, czy firmę, nasz kreator stron oparty jest na szablonach i kreatorze z prowadzeniem po treści – wystarczająco prostym dla początkujących i bogatym w funkcje dla profesjonalistów. Daje wrażenie PowerPointa, ale z większą mocą, elegancją i prostotą. Rozwiązanie, z którego będzie ci się przyjemnie korzystać.";
$_LANG['store']['siteBuilder']['introHeadline'] = "Twoja podróż online <br class=\"hidden-xs\">zaczyna się tutaj.";
