$_LANG['store']['sitelock']['emergencyPlanUpdatesTitle'] = "Aktualizacje w czasie rzeczywistym";
$_LANG['store']['sitelock']['faq'] = "FAQ";
$_LANG['store']['sitelock']['faqFiveBody'] = "Nie. Podczas skanowania witryny SiteLock pobiera odpowiednie pliki na bezpieczny serwer i tam przeprowadza skanowanie. Nie ma to wpływu na zawartość, kod, przepustowość ani zasoby serwera witryny.";
$_LANG['store']['sitelock']['faqFiveTitle'] = "Czy SiteLock wpłynie na wydajność witryny?";
$_LANG['store']['sitelock']['faqFourBodyParagraph1'] = ":vulnerabilityStrong to słabość lub błędna konfiguracja w kodzie witryny lub aplikacji internetowej, która pozwala atakującemu uzyskać pewien poziom kontroli nad witryną, a możliwe że także nad serwerem hostingowym. Większość luk jest wykorzystywana w sposób zautomatyzowany, na przykład za pomocą skanerów luk i botnetów.";
$_LANG['store']['sitelock']['faqFourBodyParagraph2'] = ":malwareStrong, skrót od złośliwe oprogramowanie (ang. malicious software), służy do zbierania poufnych danych, uzyskiwania nieautoryzowanego dostępu do witryn, a nawet przejmowania komputerów.";
$_LANG['store']['sitelock']['faqFourTitle'] = "Czym są luki w zabezpieczeniach i złośliwe oprogramowanie?";
$_LANG['store']['sitelock']['faqOneBody'] = "SiteLock zapewnia proste, szybkie i przystępne cenowo zabezpieczenia witryn o dowolnej wielkości. Założona w 2008 roku firma chroni ponad 12 milionów witryn na całym świecie. Chmurowy pakiet produktów SiteLock oferuje automatyczne wykrywanie luk w zabezpieczeniach witryn i usuwanie złośliwego oprogramowania, ochronę przed atakami DDoS, przyspieszanie witryn, oceny ryzyka witryn oraz zgodność z PCI.";
$_LANG['store']['sitelock']['faqOneBodyLearnLinkText'] = "obejrzyj film „Jak działa SiteLock”, klikając tutaj";
$_LANG['store']['sitelock']['faqOneBodyLearnMore'] = "Aby dowiedzieć się więcej o SiteLock, :learnMoreLink";
$_LANG['store']['sitelock']['faqOneTitle'] = "Czym jest SiteLock?";
$_LANG['store']['sitelock']['faqSixBody'] = "Znak Zaufania SiteLock to powszechnie rozpoznawalna odznaka bezpieczeństwa, którą można wyświetlać w witrynie. Jest wyraźnym dowodem, że witryna jest bezpieczna i wolna od złośliwego oprogramowania. Aby dodać znak do witryny, wystarczy umieścić fragment kodu dostarczony przez SiteLock w stopce witryny.";
$_LANG['store']['sitelock']['faqSixTitle'] = "Czym jest Znak Zaufania SiteLock?";
$_LANG['store']['sitelock']['faqThreeBody'] = "SiteLock dysponuje technologią umożliwiającą przeprowadzenie kompleksowego skanowania witryny, obejmującego:";
$_LANG['store']['sitelock']['faqThreeBodyList1'] = "SiteLock codziennie skanuje pliki witryny w poszukiwaniu złośliwego oprogramowania. W przypadku jego wykrycia właściciel witryny jest natychmiast powiadamiany. SiteLock oferuje także kompleksowe skanowanie, które automatycznie usuwa złośliwe oprogramowanie.";
$_LANG['store']['sitelock']['faqThreeBodyList1Title'] = "Skanowanie plików i usuwanie złośliwego oprogramowania";
$_LANG['store']['sitelock']['faqThreeBodyList2'] = "SiteLock skanuje aplikacje witryny w poszukiwaniu typowych luk, które mogłyby doprowadzić do włamania.";
$_LANG['store']['sitelock']['faqThreeBodyList2Title'] = "Skanowanie pod kątem luk w zabezpieczeniach";
$_LANG['store']['sitelock']['faqThreeBodyList3'] = "SiteLock dysponuje technologią automatycznego łatania luk w systemach zarządzania treścią (CMS).";
$_LANG['store']['sitelock']['faqThreeBodyList3Title'] = "Bezpieczeństwo aplikacji i łatanie luk w zabezpieczeniach";
$_LANG['store']['sitelock']['faqThreeTitle'] = "Jakich rodzajów problemów szuka SiteLock?";
$_LANG['store']['sitelock']['faqTitle'] = "Najczęściej zadawane pytania";
$_LANG['store']['sitelock']['faqTwoBody'] = "SiteLock zapewnia kompleksowe zabezpieczenie witryn. Codziennie skanuje witryny w celu wykrycia luk w zabezpieczeniach lub złośliwego oprogramowania. Po ich wykryciu użytkownik jest natychmiast powiadamiany. W zależności od skanera SiteLock, wszelkie złośliwe oprogramowanie w witrynie zostanie automatycznie usunięte.  W przypadku witryn opartych na systemie zarządzania treścią (CMS) SiteLock może automatycznie łatać wykryte luki.";
