$_LANG['store']['ssl']['competitiveUpgrades']['switch'] = "Przejdź na DigiCert SSL";
$_LANG['store']['ssl']['competitiveUpgrades']['validate'] = "Zweryfikuj";
$_LANG['store']['ssl']['dv']['descriptionContent'] = "<p>Certyfikaty z weryfikacją domeny to ekonomiczny i szybki sposób na wdrożenie SSL w witrynie. Certyfikaty z weryfikacją domeny potwierdzają własność domeny, ale nie przeprowadzają dodatkowej weryfikacji na poziomie organizacji.</p><p>Certyfikaty z weryfikacją domeny idealnie nadają się do witryn osobistych, blogów i mediów społecznościowych oraz wszelkich witryn, które nie przesyłają prywatnych ani poufnych informacji.  Certyfikat z weryfikacją domeny aktywuje kłódkę w przeglądarce i umożliwia korzystanie z https, zapewniając odwiedzających i klientów, że ich prywatność jest dla witryny ważna.</p>";
$_LANG['store']['ssl']['dv']['descriptionTitle'] = "Czym jest Basic DV SSL?";
$_LANG['store']['ssl']['dv']['tagline'] = "Zabezpieczenie witryny w zaledwie kilka minut!";
$_LANG['store']['ssl']['dv']['title'] = "SSL z weryfikacją domeny";
$_LANG['store']['ssl']['ev']['descriptionContent'] = "<p>EV SSL to certyfikat z rozszerzoną weryfikacją, najwyższa obecnie dostępna klasa SSL, który zapewnia witrynie większą wiarygodność i zaufanie niż certyfikat SSL z weryfikacją organizacji lub domeny.</p><p>SSL z rozszerzoną weryfikacją w większości przypadków wyświetla nazwę firmy lub witryny na zielono. Ta wyraźna weryfikacja wizualna zwiększa pewność odwiedzających, że podjęto kroki w celu potwierdzenia tożsamości odwiedzanej witryny i firmy, co zwiększa zaufanie użytkowników do witryny i jej wiarygodności – dlatego większość dużych firm i organizacji wybiera certyfikaty EV.</p>";
