$_LANG['store']['ssl']['landingPage']['certTypeInfo'] = "Certyfikaty <a href=\":dvLink\">Basic SSL (z weryfikacją domeny)</a> to najprostszy i najczęstszy typ certyfikatu SSL. Certyfikaty <a href=\":ovLink\">OV</a> i <a href=\":evLink\">EV</a> dodatkowo uwierzytelniają tożsamość firmy lub organizacji posiadającej certyfikat, co zapewnia użytkownikom większe zaufanie. <br><br>Dzięki naszym usługom certyfikatów SSL* nie trzeba co roku ręcznie konfigurować i wdrażać nowych certyfikatów. Zamówienie odnowienia generujemy automatycznie, gdy certyfikat zbliża się do końca okresu ważności. Po opłaceniu automatycznie skonfigurujemy, zweryfikujemy i udostępnimy nowy certyfikat.<br><br><small>* Domena musi być hostowana u tego samego dostawcy hostingu, który sprzedał certyfikat SSL, a serwer musi korzystać z cPanel, Plesk lub DirectAdmin.</small>";
