$_LANG['store']['ssl']['landingPage']['evs']['wildcardDescription'] = "Certyfikat wildcard SSL chroni domenę główną i nieograniczoną liczbę subdomen (na przykład mail.example.com lub ftp.example.com). Nawet jeśli samodzielnie nie utworzono żadnych subdomen, prawdopodobnie istnieje kilka subdomen dla funkcji wchodzących w skład pakietu hostingowego.";
$_LANG['store']['ssl']['landingPage']['evs']['wildcardSubtitle'] = "Certyfikat wildcard SSL to najlepszy sposób na zabezpieczenie całej witryny i ochronę użytkowników.";
$_LANG['store']['ssl']['landingPage']['faq']['a1'] = "Certyfikaty SSL umożliwiają szyfrowanie danych w internecie i bezpieczne przesyłanie danych z serwera WWW do przeglądarki. Dzięki SSL witryna może korzystać z protokołu https, a w przeglądarkach użytkowników wyświetli się kłódka wskazująca, że połączenie jest bezpieczne.";
$_LANG['store']['ssl']['landingPage']['faq']['a2'] = "Certyfikaty SSL są niezbędnym elementem internetu. Nie tylko szyfrują komunikację między komputerem a serwerem, na którym znajduje się witryna, ale także potwierdzają, że witryna jest tym, za co się podaje.";
$_LANG['store']['ssl']['landingPage']['faq']['a3'] = "Istnieją 3 różne poziomy weryfikacji, na których opierają się certyfikaty SSL: weryfikacja domeny (DV), weryfikacja organizacji (OV) i rozszerzona weryfikacja (EV). Główna różnica między typami certyfikatów dotyczy informacji, których urząd certyfikacji, taki jak RapidSSL, GeoTrust i DigiCert, wymaga i weryfikuje w celu wystawienia certyfikatu. Wyższe poziomy certyfikatów wymagają więcej informacji i często są wyświetlane na pasku przeglądarki. Na przykład EV SSL zmienia pasek przeglądarki na zielony i wyświetla odwiedzającym nazwę organizacji, aby zwiększyć zaufanie.";
$_LANG['store']['ssl']['landingPage']['faq']['a4'] = "Certyfikat Wildcard SSL zapewnia te same funkcje szyfrowania i uwierzytelniania co inne certyfikaty SSL, ale może być stosowany także do nieograniczonej liczby subdomen witryny. Certyfikat Wildcard SSL obsługuje domenę główną (example.com) oraz jej subdomeny.";
$_LANG['store']['ssl']['landingPage']['faq']['a5'] = "Certyfikaty EV, czyli z rozszerzoną weryfikacją, to najwyższa dostępna klasa SSL, która zapewnia witrynie największą wiarygodność i zaufanie. EV gwarantuje konsumentom, że ich dane osobowe i finansowe są chronione na najwyższym poziomie uwierzytelnienia. Przeprowadzane są dodatkowe weryfikacje, takie jak sprawdzenie rejestrów firm, danych kontaktowych wnioskodawcy oraz tego, czy firma istnieje co najmniej 3 lata. Certyfikaty EV najlepiej nadają się do stron o krytycznym znaczeniu dla firmy.";
$_LANG['store']['ssl']['landingPage']['faq']['a6'] = "Możesz przejść do nas w dowolnym momencie.  Oferujemy bardzo konkurencyjne ceny, a jeśli masz już certyfikat, doliczymy pozostały okres ważności obecnego certyfikatu SSL konkurencji, maksymalnie do dodatkowych 12 miesięcy.";
