$_LANG['store']['ssl']['wildcard']['descriptionContent'] = "<p>Wildcard SSL umożliwia zabezpieczenie nieograniczonej liczby subdomen jednym certyfikatem. To świetne rozwiązanie dla osób hostujących lub zarządzających wieloma witrynami albo stronami w tej samej domenie. Jednorazowy koszt certyfikatu obejmuje również subdomeny, które zostaną dodane w przyszłości.</p><p>W przeciwieństwie do standardowego certyfikatu SSL, wystawianego wyłącznie dla jednej w pełni kwalifikowanej nazwy domeny (FQDN), np. www.example.com, co oznacza, że może zabezpieczać tylko dokładnie tę domenę, certyfikat Wildcard SSL jest wystawiany dla *.example.com, gdzie gwiazdka oznacza wszystkie możliwe subdomeny.</p><p>Wildcard SSL jest opcją dostępną dla certyfikatów SSL DV i OV.</p>";
