$_LANG['store']['threesixtymonitoring']['faq']['a1'] = "Website Monitoring testuje witryny pod kątem dostępności, wydajności i ogólnego działania. Sprawdza, czy witryna działa i jest dostępna dla odwiedzających. Wyniki monitorowania pozwalają usunąć problemy, zanim wpłyną na działalność firmy.";
$_LANG['store']['threesixtymonitoring']['faq']['a10'] = "Server Monitoring regularnie skanuje i śledzi stan serwera, w tym procesor, czasy ładowania, statystyki sieciowe, pamięć, użycie dysku i inne parametry, aby szybko wykrywać i rozwiązywać problemy.";
$_LANG['store']['threesixtymonitoring']['faq']['a11'] = "Pełna kontrola witryny chroni obecność online przed błędami. Skanuje całą witrynę lub sklep internetowy i wykrywa martwe linki, uszkodzone obrazy, błędy JavaScript i wiele innych anomalii, pomagając unikać problemów z witryną.";
$_LANG['store']['threesixtymonitoring']['faq']['a2'] = "Website Monitoring przeprowadza testy witryny w regularnych odstępach czasu (co 1, 5 lub 10 minut, w zależności od planu). Testy te wykrywają problemy z witryną. Po wykryciu problemu 360 Monitoring wysyła alert i zapisuje zdarzenie do późniejszej analizy.";
$_LANG['store']['threesixtymonitoring']['faq']['a3'] = "Narzędzia i procesy Performance Monitoring sprawdzają, jak działa system, monitorując zasoby, takie jak użycie procesora, zużycie pamięci, użycie dysku, wydajność wejścia/wyjścia (I/O) i dostępność sieci. 360 Monitoring śledzi wszystkie te wskaźniki, aby wszystko działało płynnie.";
$_LANG['store']['threesixtymonitoring']['faq']['a4'] = "Performance Monitoring jest kluczowy dla wykrywania problemów z wydajnością, zanim zaszkodzą firmie. Jego wyniki dotyczące zasobów systemowych pozwalają także z wyprzedzeniem planować przyszłe potrzeby.";
$_LANG['store']['threesixtymonitoring']['faq']['a5'] = "Dzięki SSL Monitoring można śledzić certyfikaty SSL i planować z wyprzedzeniem ich wygaśnięcie, zapewniając bezproblemowe zarządzanie certyfikatami.";
$_LANG['store']['threesixtymonitoring']['faq']['a6'] = "Monitorowanie można prowadzić z dowolnego miejsca na świecie; lokalizacje monitorowania znajdują się w Australii, Kanadzie, Finlandii, Francji, Niemczech, Japonii, Meksyku, Holandii, Szwecji, Wielkiej Brytanii i Stanach Zjednoczonych.";
$_LANG['store']['threesixtymonitoring']['faq']['a7'] = "360 Monitoring obsługuje języki: angielski, niemiecki, japoński, hiszpański, włoski, brazylijski portugalski, francuski i rosyjski.";
$_LANG['store']['threesixtymonitoring']['faq']['a8'] = "Tak, plan można zmienić na wyższy w dowolnym momencie.";
$_LANG['store']['threesixtymonitoring']['faq']['a9'] = "Wszystkie plany płatne umożliwiają nieograniczoną liczbę alertów w wielu kanałach. Niektórzy operatorzy mogą naliczać dodatkowe opłaty za transmisję danych lub wiadomości SMS.";
