$_LANG['store']['xoviNow']['audience']['freelancersDesc'] = "XOVI NOW zaprojektowano tak, aby od razu przynosił korzyści zarówno osobistej stronie, jak i stronom klientów – od pierwszego audytu witryny po rekomendacje poprawiające wyniki w wyszukiwarkach.";
$_LANG['store']['xoviNow']['audience']['freelancersTitle'] = "Freelancerzy";
$_LANG['store']['xoviNow']['audience']['smbizDesc'] = "Nie trzeba być ekspertem SEO, aby poprawić pozycje firmy w Google. XOVI NOW wskaże najlepsze słowa kluczowe dla firmy, a jednocześnie będzie monitorować wyniki konkurencji.";
$_LANG['store']['xoviNow']['audience']['smbizTitle'] = "Małe i średnie przedsiębiorstwa";
$_LANG['store']['xoviNow']['cartShortDescription'] = "Popraw wydajność witryny dzięki dokładnym, niezawodnym i łatwym w użyciu rankingom witryn, słowom kluczowym oraz doradcy.";
$_LANG['store']['xoviNow']['cartTitle'] = "Narzędzia SEO";
$_LANG['store']['xoviNow']['faq1'] = "Czym jest SEO?";
$_LANG['store']['xoviNow']['faq10'] = "Czym jest widoczność projektu?";
$_LANG['store']['xoviNow']['faq10ans'] = "<p>Być może pomyślałeś: „Chwileczkę, ale nie interesuje mnie widoczność dla słów kluczowych, które nie mają nic wspólnego z moją firmą”. I masz rację. Widoczność to świetny wskaźnik pozwalający ocenić ogólne wyniki i porównywać strony, ale nie jest dopasowana do konkretnego zestawu słów kluczowych.</p><p>Dlatego udostępniamy <em>Widoczność projektu</em>. Ta metryka jest obliczana tak samo jak Widoczność, ale zamiast 500 000 słów kluczowych z różnych branż opiera się wyłącznie na słowach kluczowych z Rank Trackera.</p><p>Innymi słowy, Widoczność projektu to indywidualny wskaźnik widoczności dla unikalnego zestawu słów kluczowych istotnych dla firmy.</p><p>Widoczność projektu znajdziesz tutaj: <em>Projekty → Rank Tracker → Widoczność</em>.</p><p>W Rank Trackerze można również śledzić pozycje konkurencji. Dzięki temu zobaczysz także jej Widoczność projektu, co pozwala na znacznie bardziej realistyczne porównanie. Nawet jeśli oferta produktów lub usług konkurencji nieco się różni, Widoczność projektu uwzględnia wyłącznie słowa kluczowe, które rzeczywiście są wspólne.</p>";
$_LANG['store']['xoviNow']['faq11'] = "Dlaczego wskaźnik Widoczności jest przydatny?";
$_LANG['store']['xoviNow']['faq11ans'] = "<p>Wskaźnik Widoczności można wykorzystać jako miarę ogólnej skuteczności SEO, problemów i potencjału optymalizacji.</p><p><strong>1. Ogólny obraz skuteczności SEO</strong></p><p>Można śledzić pozycje pojedynczych słów kluczowych i wiedzieć, na którym miejscu się znajdują. To ważne. Jednak śledzenie pozycji nie daje spojrzenia z lotu ptaka na ogólną poprawę rankingów – Widoczność tak. Gdy działania SEO są skuteczne, a pozycje rosną, rośnie również wskaźnik Widoczności.</p><p><strong>2. Diagnozowanie problemów SEO</strong></p><p>Nagły spadek Widoczności wskazuje na problemy w działaniach SEO. Widoczność działa jak alarm. Jeśli znacząco spadnie, zacznij szukać przyczyny. Oto lista najczęstszych powodów:</p><ul><li>Nałożono <strong>karę Google</strong>. Sprawdź powiadomienia w Search Console i przestrzegaj <a href=\":googleWebmasterGuidelinesUrl\" target=\"_blank\">wytycznych Google Search Essentials</a>.</li><li>Zmieniono algorytm Google i są tego skutki. Warto sprawdzić ostatnie <strong>aktualizacje Google</strong> i czego dotyczyły.</li><li>Konkurencja zoptymalizowała swoje strony i treści i teraz Cię wyprzedza. Porównaj jej (historyczną) <strong>Widoczność</strong> z własną. Za pomocą <a href=\":waybackMachineUrl\" target=\"_blank\">Wayback Machine</a> możesz sprawdzić, jak zmieniły się jej treści.</li><li>Strona została przebudowana bez uwzględnienia SEO. Na przykład sprawdź <em>robots.txt</em> i <em>.htaccess</em> pod kątem przypadkowo zablokowanych stron, zwiększonej liczby kodów 404, błędnych przekierowań 301 i linków wewnętrznych.<br><br>Treści zostały zmienione w sposób, który nie pomógł w rankingach. Warto rozważyć cofnięcie zmian.<br><br>Strona ma problemy techniczne. Uruchom <em>Audyt witryny</em> lub sprawdź w <strong><em>Doradcy</em></strong> otwarte zadania techniczne. W panelu administracyjnym sprawdź nieaktualne, niedawno zaktualizowane lub niekompatybilne <strong>wtyczki</strong>, które mogą powodować problemy.<br><br>Przyczyną są problemy z hostingiem. Sprawdź, czy dostawca hostingu wprowadzał ostatnio zmiany, został zhakowany, przeniósł serwery lub miał awarie techniczne. Sprawdź też, czy serwer nie ma problemów.</li></ul><p>Pamiętaj, że ta lista nie jest wyczerpująca. Może występować jednocześnie kilka z tych przyczyn lub zupełnie inne.</p><p><strong>3. Porównanie z konkurencją</strong></p><p>Widoczność to doskonała metryka do szybkiego porównania dwóch lub więcej stron. Można sprawdzić swoją Widoczność na tle konkurencji. Kto kogo wyprzedza? Czy konkurent w przeszłości osiągał lepsze wyniki lub odwrotnie? Kto prowadzi w stawce i jak duża jest różnica względem najgroźniejszego rywala? Odpowiedzi na te pytania pomagają opracować strategię SEO, która pozwoli znaleźć się (i pozostać) na szczycie w swojej niszy.</p><p><strong>4. Śledzenie rozwoju Widoczności w czasie na podstawie danych historycznych</strong></p><p>Chcesz wiedzieć, jak strona radziła sobie na przestrzeni czasu? Udostępniamy dane historyczne sięgające 2009 roku, bez wahań sezonowych. Dzięki temu można śledzić i porównywać historyczną Widoczność oraz jej rozwój w długich okresach.</p>";
$_LANG['store']['xoviNow']['faq12'] = "Jak poprawić wskaźnik Widoczności?";
$_LANG['store']['xoviNow']['faq12ans'] = "<p>Krótka odpowiedź: nie czyń poprawy Widoczności celem strategii SEO.</p><p>Długa odpowiedź: Widoczność <em>odzwierciedla</em> jakość pozycji w jednej metryce, ale nie prowadzi do lepszych pozycji. Celem powinna być poprawa pozycji dla istotnych słów kluczowych, których potencjalni klienci rzeczywiście używają, szukając produktów i usług takich jak Twoje. Poprawa pozycji poprawi także Widoczność. Jednak to pozycje naprawdę mają znaczenie.</p><p>Z reguły wskaźnik Widoczności będzie wyższy, jeśli</p><ul><li>adresy URL domeny zajmują dobre pozycje,</li><li>liczba zaindeksowanych adresów URL z dobrymi pozycjami jest wysoka,</li><li>strona jest wysoko dla słów kluczowych o dużej liczbie wyszukiwań.</li></ul>";
$_LANG['store']['xoviNow']['faq1ans'] = "<p>SEO to skrót od Search Engine Optimization (optymalizacja pod kątem wyszukiwarek). Jest to podstawowa strategia marketingu internetowego, której celem jest przyciąganie potencjalnych klientów na stronę. Jej zadaniem jest optymalizacja strony tak, aby zajmowała czołowe pozycje dla wybranych słów kluczowych w wyszukiwarkach. Cel ten osiąga się dzięki strategicznym działaniom poprawiającym techniczną konfigurację i treści strony oraz pozyskiwaniu linków zwrotnych z innych domen.</p><p>SEO dzieli się na trzy ogólne kategorie:</p><ol><li>Słowa kluczowe i pozycje</li><li>SEO on-page</li><li>SEO off-page</li></ol><p>Specjaliści SEO podejmują działania, aby spełnić czynniki rankingowe wyszukiwarki w każdej kategorii. Wyszukiwarki wykorzystują czynniki rankingowe do określenia pozycji, na której wyświetlają stronę w wynikach wyszukiwania.</p>";
$_LANG['store']['xoviNow']['faq2'] = "Dlaczego SEO jest potrzebne?";
$_LANG['store']['xoviNow']['faq2ans'] = "<p>Każdego dnia miliony ludzi korzystają z wyszukiwarek, aby znaleźć informacje lub usługi z każdej dziedziny życia: przepisy, poradniki, produkty, loty, nawigację, bilety, rozrywkę i wiele więcej. Większość osób porusza się po sieci za pomocą wyszukiwarek, aby znaleźć odpowiedzi na pytania i rozwiązania swoich problemów.</p><p>Badania pokazują, że 68% ruchu w sieci pochodzi z wyszukiwarek. 53% tego ruchu pochodzi z wyników organicznych – wyników niebędących reklamami (płatne wyszukiwanie), które można poprawiać dzięki SEO.</p><img src=\":image1\"><p>Innymi słowy, wyniki organiczne (SEO) i płatne (SEA, reklamy w wynikach wyszukiwania) stanowią lwią część ruchu w sieci.</p><p>Nawet to, dokąd udajemy się offline, jest w znacznym stopniu kształtowane przez wyszukiwarki: korzystamy z Google i Apple Maps oraz lokalnych wyników wyszukiwania, aby znaleźć miejsca i pobliskie usługi, takie jak fryzjerzy, supermarkety, restauracje i lekarze. Cel podróży wybieramy na podstawie opinii w sieci. Usługi oparte na wyszukiwarkach prowadzą nas tam samochodem, komunikacją publiczną lub pieszo.</p><p>A teraz wyobraź sobie, że Twoja firma, produkty i usługi nie są wyświetlane w wynikach wyszukiwania. Że ludzie nie mogą Cię znaleźć w sieci, aby kupić produkty lub trafić do stacjonarnej firmy. Najprawdopodobniej wybiorą wtedy konkurencję.</p>";
$_LANG['store']['xoviNow']['faq3'] = "Co SEO może dla mnie zrobić?";
$_LANG['store']['xoviNow']['faq3ans'] = "<p>Dzięki SEO użytkownicy mogą znaleźć firmę, produkty i usługi w sieci – i je kupić. Oznacza to, że ludzie mogą znaleźć Cię online, a także znacznie łatwiej offline.</p><p>SEO zwiększa szanse na wyświetlanie na czołowych pozycjach dla najważniejszych dla firmy słów kluczowych. Im lepsza pozycja, tym więcej osób trafi na stronę – najlepiej na pierwszej stronie (lub w pierwszej dziesiątce) wyników wyszukiwania.</p><p><strong>Dlaczego pierwsza strona?</strong></p><p>Dobre pytanie. Badania wykazały, że 31,7% użytkowników klika pierwszy wynik organiczny (pozycja pierwsza), a aż 75,1% wszystkich kliknięć trafia do trzech pierwszych wyników. Potem liczba kliknięć gwałtownie spada z każdą kolejną pozycją.</p><img src=\":image2\"><p>To zachowanie pokazuje, że użytkownicy rzadko przeglądają drugą stronę lub dalsze wyniki, a tym bardziej w nie klikają.</p><img src=\":image3\"><p>Dlatego firmy muszą być obecne na pierwszej stronie wyników wyszukiwania, przynajmniej dla istotnych słów kluczowych.</p><p>Krótko mówiąc: dla freelancerów i właścicieli firm kluczowe jest, aby</p><ol><li>posiadać stronę internetową lub inną formę obecności w sieci, nawet jeśli oferują produkty lub usługi offline,</li><li>prowadzić działania SEO, aby mieć pewność, że zajmują pierwszą stronę wyników dla istotnych słów kluczowych.</li></ol>";
$_LANG['store']['xoviNow']['faq4'] = "Dlaczego słowa kluczowe są ważne?";
$_LANG['store']['xoviNow']['faq4ans'] = "<p><em>Słowo kluczowe</em> to termin techniczny określający zapytania wyszukiwania (słowa, frazy, zdania i pytania). Dzięki nim użytkownicy znajdują treści, które odpowiadają na ich pytania i dostarczają rozwiązań. Mówiąc najprościej, słowo kluczowe to połączenie między użytkownikami a stroną. Wyszukiwarki porównują słowa kluczowe ze stronami, szukając treści o najwyższej trafności.</p><p>Duża część SEO polega na identyfikacji słów kluczowych, które mogą przyciągnąć na stronę odpowiedni ruch – innymi słowy, potencjalnych klientów. W tym celu trzeba określić frazy (czyli słowa kluczowe), których ludzie używają, szukając ofert takich jak Twoja. Ten proces nazywa się badaniem słów kluczowych. W idealnej sytuacji badanie słów kluczowych dostarcza listę słów obejmujących zapytania na wszystkich etapach ścieżki klienta.</p>";
$_LANG['store']['xoviNow']['faq5'] = "Czym jest optymalizacja słów kluczowych?";
$_LANG['store']['xoviNow']['faq5ans'] = "<p>Wiemy już, że trafność jest kluczowym czynnikiem zajęcia czołowej pozycji w wynikach wyszukiwania. Aby tworzyć trafne treści, omów tematy i pytania związane ze słowem kluczowym na osobnej podstronie lub pod osobnym adresem URL. Następnie zadbaj, aby słowo kluczowe pojawiło się w najważniejszych miejscach strony.</p><p>Załóżmy, że prowadzisz firmę lodziarską. Jednym ze słów kluczowych jest <em>lodowa kanapka s'mores</em>. Skupiasz się więc na wszystkim, co dotyczy <em>lodowej kanapki s'mores</em>.</p><p>Stwórz stronę z przepisem na <em>lodową kanapkę s'mores</em>, na której użytkownicy znajdą łatwy do wykonania przepis, zdjęcia lub filmy oraz odpowiedzi na ewentualne pytania. <em>Lodowa kanapka s'mores</em> to główne słowo kluczowe, które powinno pojawić się w adresie URL, tytule, nagłówkach i innych miejscach strony.</p><p>Dedykowana i zoptymalizowana pod słowa kluczowe strona ułatwia wyszukiwarkom – a także użytkownikom – ustalenie, czego dotyczy strona. Dzięki temu mogą ją wyświetlać na dobrych pozycjach w powiązanych wynikach wyszukiwania.</p>";
$_LANG['store']['xoviNow']['faq6'] = "Jak korzystać z Doradcy";
$_LANG['store']['xoviNow']['faq6ans'] = "<p>Najpierw zapoznaj się z tablicą Doradcy, klikając Doradca na górnym pasku nawigacji. To tablica Kanban, która pomaga porządkować zadania według statusu. Zadania są oznaczone kolorami według ważności:</p><ul><li><strong>Czerwony:</strong> wysoka. Rozwiąż jak najszybciej.</li><li><strong>Żółty:</strong> średnia. Zajmij się nimi wkrótce.</li><li><strong>Niebieski:</strong> niska. Miej je na uwadze i rozwiąż, gdy będzie to możliwe.</li></ul><img src=\":image1\"><p>Zadania można przeciągać i upuszczać po ich wykonaniu, przypisywać je innym użytkownikom (w zależności od planu) oraz filtrować według osoby przypisanej.</p><p>Jak wspomniano wyżej, zadania to połączenie standardowych podstawowych działań SEO oraz problemów wykrytych w cotygodniowych automatycznych audytach strony.</p>";
$_LANG['store']['xoviNow']['faq7'] = "Chcę uzyskać Doradcę dla innych stron. Jak to zrobić?";
$_LANG['store']['xoviNow']['faq7ans'] = "<p>Pamiętaj, że do działania funkcji Doradcy potrzebny jest <em>Projekt</em>. Ponadto większość zadań Doradcy jest dopasowana do strony projektu (zwykle własnej lub klienta). Jeśli zarządzasz więcej niż jedną stroną, dla każdej z nich musisz utworzyć dodatkowy projekt.</p><p>Aby dodać inny projekt lub przełączyć się na niego, kliknij menu <em>Projekty</em> na górnym pasku nawigacji. W zależności od planu może być konieczne jego ulepszenie, aby dodać kolejny projekt.</p>";
$_LANG['store']['xoviNow']['faq8'] = "Jak przypisać zadania innym użytkownikom?";
$_LANG['store']['xoviNow']['faq8ans'] = "<p>Aby przypisać zadanie innym użytkownikom, potrzebny jest plan umożliwiający dodatkowych użytkowników. Jeśli plan obejmuje dodatkowych użytkowników, w Doradcy i zadaniach znajduje się menu Osoba przypisana. Wystarczy wybrać użytkownika, któremu ma zostać przypisane zadanie lub według którego ma być filtrowany Doradca. Aby dodać nowego użytkownika, kliknij awatar profilu, a następnie <em>Użytkownicy</em>. Jeśli plan nie obejmuje dodatkowych użytkowników, menu <em>Osoba przypisana</em> nie będzie widoczne w Doradcy ani w zadaniach. Aby dodać użytkowników, ulepsz plan.</p>";
$_LANG['store']['xoviNow']['faq9'] = "Są zadania, które już zostały wykonane. Dlaczego się pojawiają?";
$_LANG['store']['xoviNow']['faq9ans'] = "<p>Istnieją dwa powody, dla których mogą pojawiać się zadania już rozwiązane lub zrealizowane. Jak wspomniano wyżej, zadania to połączenie podstawowych działań SEO oraz problemów wykrytych w cotygodniowych automatycznych audytach strony.</p><p>Po pierwsze, zadania dotyczące podstawowych działań SEO są takie same dla wszystkich i nie są dopasowane do konkretnej strony ani firmy. Na przykład nie wiemy, czy założono konto Google dla firmy i skonfigurowano Search Console, ani czy zainstalowano wtyczki SEO. Jeśli tak – świetna robota! Wystarczy oznaczyć takie zadania jako wykonane.</p><p>Drugi powód jest taki, że Doradca jest automatycznie aktualizowany na podstawie wyników automatycznych cotygodniowych audytów witryny. Innymi słowy, jeśli audyt witryny wykryje problemy dotyczące zadania wykonanego w przeszłości, zostanie ono automatycznie zaktualizowane i pojawi się w sekcji Otwarte.</p>";
